  console.log('=== search empty? ===', await page.evaluate(() => window.location.search));
  console.log('=== hash ===', await page.evaluate(() => window.location.hash));
  console.log('=== getInfo responses ===\n' + reqs.join('\n'));
  console.log('=== bodyText(400) ===\n' + bodyText);
  console.log('=== logs(last 40) ===\n' + logs.slice(-40).join('\n'));
  await browser.close();
})();

